parameters.jsCode:
const client = $('Fetch Active Clients').item.json;
const raw = $input.item.json;
const cols = (raw.data?.cols || []).map(c => c.name);
const rows = raw.data?.rows || [];
const metrics = rows.map(r => Object.fromEntries(cols.map((c, i) => [c, r[i]])));

// Locked/filtered public dashboard link the client can click to view live data
const dashboardUrl = `${$env.METABASE_URL}/public/dashboard/${$env.METABASE_CLIENT_DASHBOARD_PUBLIC_UUID}?client_id=${client.odoo_lead_id}`;

return [{
  json: {
    ...client,
    metrics_json: JSON.stringify(metrics).slice(0, 4000),
    dashboard_url: dashboardUrl
  }
}];

parameters.jsonBody:
={
  "model": "qwen2.5:7b",
  "stream": false,
  "prompt": "You write short, friendly weekly client update emails for a digital marketing/AI agency. Client: {{$json.company}}. Raw weekly metrics data (JSON): {{$json.metrics_json}}.\n\nReturn ONLY a valid JSON object with keys: headline (one sentence, the single best result this week), bullet_points (array of up to 4 short strings, plain language, no jargon), next_week_focus (one sentence). No text outside the JSON."
}

parameters.jsCode:
let parsed;
try {
  const raw = $input.item.json.response || '{}';
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = { headline: 'Here is your weekly update.', bullet_points: [], next_week_focus: '' };
}

return [{
  json: {
    ...$('Parse Metrics + Build Dashboard Link').item.json,
    headline: parsed.headline || '',
    bullet_points: parsed.bullet_points || [],
    next_week_focus: parsed.next_week_focus || ''
  }
}];

